def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 3 or no_water_days >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 140:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    need = 0.0
    if hp <= 2:
        need = 1.0
    elif hp <= 4:
        need = 0.75
    elif no_water_days >= 1:
        need = 0.7
    elif hp <= 6:
        need = 0.45
    else:
        need = 0.2

    pressure = 0.0
    if highest_prev >= 160:
        pressure = 1.0
    elif highest_prev >= 120:
        pressure = 0.8
    elif highest_prev >= 80:
        pressure = 0.55
    elif highest_prev > 0:
        pressure = 0.3

    if hp >= 7 and no_water_days == 0 and scarcity < 0.45 and pressure >= 0.8:
        return float(max(0.0, min(budget, DAILY_SALARY * 0.18)))

    if hp <= 2 or no_water_days >= 2:
        emergency = max(DAILY_SALARY * 1.15, highest_prev + 6.0, avg_prev + 10.0)
        if rich_count >= 2:
            emergency = max(emergency, DAILY_SALARY * 1.45)
        return float(max(0.0, min(budget, emergency)))

    base = DAILY_SALARY * (0.28 + 0.55 * need + 0.35 * scarcity)

    if pressure >= 0.8:
        if need >= 0.7 or scarcity >= 0.6:
            base = max(base, min(highest_prev + 3.0, DAILY_SALARY * 1.5))
        else:
            base = min(base, DAILY_SALARY * 0.32)
    elif pressure >= 0.55:
        base = max(base, min(highest_prev + 2.0, DAILY_SALARY * 1.15))
    elif highest_prev > 0:
        base = max(base, highest_prev + 1.0)

    if desperate_count >= 2 and (hp <= 5 or scarcity >= 0.5):
        base = max(base, DAILY_SALARY * 0.95)

    if day >= 8 and hp <= 5:
        base = max(base, DAILY_SALARY * 0.95)

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if days_left > 0 and hp >= 6:
        reserve_floor = min(budget * 0.45, days_left * DAILY_SALARY * 0.18)

    affordable = max(0.0, budget - reserve_floor)
    if need >= 0.7:
        affordable = budget

    bid = min(base, affordable)
    if bid <= 0 and budget > 0:
        bid = min(budget, DAILY_SALARY * 0.12)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Pressure estimate: if others bid near/above salary, they likely secure water aggressively.
    aggressive_threshold = DAILY_SALARY * 0.85  # 76.5

    # Base strategy: if we are low HP or have accumulated no-water days, bid higher.
    # If others were aggressive yesterday, slightly overbid to secure.
    if hp <= 2.0 or no_water_days >= 2:
        target = max(DAILY_SALARY * 0.85, highest_prev_bid * 1.02)
    elif highest_prev_bid >= aggressive_threshold:
        # Healthy but likely contested: bid enough to not lose.
        target = max(DAILY_SALARY * 0.65, highest_prev_bid * 0.98)
    else:
        # Less contested: conserve budget.
        target = max(DAILY_SALARY * 0.45, highest_prev_bid * 0.9)

    # Supply-aware cap: when supply is tight, we should be more competitive.
    # supply range: 15..25; map to a multiplier.
    if supply <= MIN_SUPPLY:
        mult = 1.10
    elif supply >= MAX_SUPPLY:
        mult = 0.95
    else:
        # linear interpolation between 1.10 at 15 and 0.95 at 25
        mult = 1.10 - (float(supply) - float(MIN_SUPPLY)) * (1.10 - 0.95) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))

    target *= mult

    # Hard budget/safety limits: don't overspend early; keep some reserve.
    # Reserve more when hp is good.
    if hp >= 6.0:
        reserve_frac = 0.25
    elif hp >= 3.0:
        reserve_frac = 0.15
    else:
        reserve_frac = 0.05

    max_affordable = max(0.0, budget * (1.0 - reserve_frac))
    bid = min(max_affordable, target)

    # Ensure non-negative and at least some minimal bid if budget allows.
    if bid < 0.0:
        bid = 0.0
    if bid == 0.0 and budget > 0.0:
        bid = min(budget, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    avg_prev = 0
    if prev_bids:
        avg_prev = sum(prev_bids) / len(prev_bids)

    # Determine base bid
    if hp <= 2:
        base = 130
    elif hp <= 5:
        base = 100
    else:
        base = 80

    # Adjust based on supply
    if supply >= 22:
        base = max(60, base - 15)
    elif supply <= 17:
        base = min(DAILY_SALARY * 0.95, base + 20)

    # Adjust based on opponents
    if avg_prev > 0:
        # If opponents are aggressive, we need to be competitive but not overpay
        if avg_prev > 140:
            if hp <= 2:
                target = min(budget, avg_prev + 10)
            else:
                target = min(budget, avg_prev - 5)
        else:
            target = min(budget, max(base, avg_prev + 2))
    else:
        target = min(budget, base)

    # Ensure non-negative, cap at budget
    return max(0, int(target))
